import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);"

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define TILE 32

__global__ void upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N
) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int row_tile = blockIdx.y;
    const int col_tile = blockIdx.x;

    const int row = row_tile * TILE + ty;
    const int col = col_tile * TILE + tx;

    float acc = 0.0f;

    // Product of upper triangular matrices is upper triangular.
    // For output tile (row_tile, col_tile), only k tiles in [row_tile, col_tile] contribute.
    if (row_tile <= col_tile) {
        for (int kt = row_tile; kt <= col_tile; ++kt) {
            const int a_r = row_tile * TILE + ty;
            const int a_c = kt * TILE + tx;
            const int b_r = kt * TILE + ty;
            const int b_c = col_tile * TILE + tx;

            float av = 0.0f;
            float bv = 0.0f;

            if (a_r < N && a_c < N && a_r <= a_c) {
                av = A[a_r * N + a_c];
            }
            if (b_r < N && b_c < N && b_r <= b_c) {
                bv = B[b_r * N + b_c];
            }

            As[ty][tx] = av;
            Bs[ty][tx] = bv;
            __syncthreads();

            #pragma unroll
            for (int kk = 0; kk < TILE; ++kk) {
                acc += As[ty][kk] * Bs[kk][tx];
            }
            __syncthreads();
        }
    }

    if (row < N && col < N) {
        C[row * N + col] = (row <= col) ? acc : 0.0f;
    }
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have the same shape");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const int N = static_cast<int>(A.size(0));
    auto C = torch::empty_like(A);

    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    auto stream = at::cuda::getCurrentCUDAStream();

    upper_triangular_matmul_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

_ext = load_inline(
    name="upper_triangular_matmul_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["triu_matmul_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return _ext.triu_matmul_cuda(A, B)

